insert into public.properties (id, kind, status, sort_order, data) values ('h1', 'hotel', 'published', 10, $ds${"id":"h1","category":"budget","name":{"en":"Cataract Layalina","ar":"كاتاراكت ليالينا","ru":"Cataract Layalina","de":"Cataract Layalina","it":"Cataract Layalina","tr":"Cataract Layalina"},"description":{"en":"4-star hotel with sea view","ar":"فندق 4 نجوم بإطلالة على البحر","ru":"Роскошный 5-звездочный отель с видом на море","de":"Luxus-5-Sterne-Hotel mit Meerblick","it":"Hotel di lusso 5 stelle con vista mare","tr":"Deniz manzaralı lüks 5 yıldızlı otel"},"fullDescription":{"en":"Experience unparalleled luxury at Discover Grand Hotel. Featuring stunning Red Sea views, world-class amenities, and exceptional service that defines the essence of Sharm El Sheikh hospitality.","ar":"استمتع بتجربة فخامة لا مثيل لها في فندق ديسكفر جراند، بإطلالات ساحرة على البحر الأحمر ومرافق عالمية المستوى وخدمة استثنائية تجسد روح الضيافة في شرم الشيخ.","ru":"Ощутите непревзойденную роскошь в Discover Grand Hotel — потрясающий вид на Красное море, первоклассные удобства и безупречный сервис, отражающий дух гостеприимства Шарм-эль-Шейха.","de":"Erleben Sie unvergleichlichen Luxus im Discover Grand Hotel mit atemberaubendem Blick auf das Rote Meer, erstklassigen Annehmlichkeiten und außergewöhnlichem Service.","it":"Vivi un lusso senza pari al Discover Grand Hotel, con splendide vedute sul Mar Rosso, servizi di livello mondiale e un'ospitalità eccezionale, tipica di Sharm El Sheikh.","tr":"Discover Grand Hotel'de eşsiz bir lüks deneyimi yaşayın — büyüleyici Kızıldeniz manzarası, dünya standartlarında olanaklar ve Sharm El Sheikh misafirperverliğini yansıtan üstün hizmet."},"price":3800,"rating":5,"reviews":234,"location":{"en":"123 Naama Bay, Sharm El Sheikh","ar":"١٢٣ خليج نعمة، شرم الشيخ","ru":"Naama Bay 123, Шарм-эль-Шейх","de":"Naama Bay 123, Sharm El Sheikh","it":"Naama Bay 123, Sharm El Sheikh","tr":"Naama Bay 123, Sharm El Sheikh"},"image":"https://www.hotelsharmelsheikhegypt.com/data/Pics/OriginalPhoto/10769/1076965/1076965390/pic-cataract-resort-aqua-park-naama-bay-sharm-el-sheikh-42.JPEG","images":["https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=800&q=90","https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=90","https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=800&q=90"],"amenities":{"en":["Free WiFi","Breakfast","Pool","Spa","Gym","Parking"],"ar":["واي فاي مجاني","إفطار","مسبح","سبا","صالة رياضية","موقف سيارات"],"ru":["Бесплатный Wi-Fi","Завтрак","Бассейн","Спа","Тренажерный зал","Парковка"],"de":["Kostenloses WLAN","Frühstück","Pool","Spa","Fitnessstudio","Parkplatz"],"it":["WiFi gratuito","Colazione","Piscina","Spa","Palestra","Parcheggio"],"tr":["Ücretsiz WiFi","Kahvaltı","Havuz","Spa","Spor Salonu","Otopark"]},"bestseller":true,"rooms":[{"type":{"en":"Deluxe Sea View","ar":"ديلوكس بإطلالة على البحر","ru":"Делюкс с видом на море","de":"Deluxe Meerblick","it":"Deluxe Vista Mare","tr":"Deniz Manzaralı Delüks"},"price":3800,"size":"35m²","beds":{"en":"1 King Bed","ar":"سرير كينج واحد","ru":"1 кровать king-size","de":"1 Kingsize-Bett","it":"1 letto king","tr":"1 King Yatak"},"guests":2,"image":"https://images.unsplash.com/photo-1631049307264-da0ec9d70304?auto=format&fit=crop&w=400&q=80","description":{"en":"A bright, airy room with floor-to-ceiling windows framing the Red Sea. Soft linens, a marble bathroom, and a private balcony make this the hotel's signature room.","ar":"غرفة مشرقة وواسعة بنوافذ ممتدة من الأرض إلى السقف تطل على البحر الأحمر، مع مفروشات ناعمة وحمام رخامي وشرفة خاصة.","ru":"Светлый просторный номер с панорамными окнами и видом на Красное море, мраморной ванной комнатой и собственным балконом.","de":"Ein helles, luftiges Zimmer mit bodentiefen Fenstern zum Roten Meer, weicher Bettwäsche, Marmorbad und privatem Balkon.","it":"Camera luminosa con finestre a tutta altezza sul Mar Rosso, biancheria morbida, bagno in