insert into public.properties (id, kind, status, sort_order, data) values ('e1', 'excursion', 'published', 10, $ds${"id":"e1","category":"Boat trip","title":{"ar":"رحلة سنوركل رأس محمد","en":"Ras Mohammed Snorkeling Trip","ru":"Снорклинг-тур в Рас-Мохаммед","de":"Ras-Mohammed-Schnorcheltour","it":"Escursione Snorkeling a Ras Mohammed","tr":"Ras Muhammed Şnorkel Turu"},"price":1700,"rating":4.8,"reviews":268,"duration":{"ar":"يوم كامل (٨ ساعات)","en":"Full Day (8h)","ru":"Целый день (8 ч)","de":"Ganzer Tag (8 Std.)","it":"Giornata intera (8h)","tr":"Tam Gün (8s)"},"image":"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR198euI0KuyPgFLPb62ocPQNohqGHLSbCezSgbAY6Cc4WZUHLTTp4snMo&s=10","images":["https://media-cdn.tripadvisor.com/media/attractions-splice-spp-674x446/10/46/40/61.jpg","https://egyptra.pro/img.php?src=uploads%2Fproducts%2Fimg_cfdc48ab0be8b871.webp&w=740&h=555&crop=1&q=72","https://dynamic-media.tacdn.com/media/photo-o/2f/38/6e/8d/caption.jpg?w=1100&h=800&s=1","https://dynamic-media.tacdn.com/media/photo-o/2f/38/fb/05/caption.jpg?w=1100&h=800&s=1","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/edb33505f3ccc56849da55242531fcac8530659a06e8af69cd304df5cabf0315.jpeg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/67b53f10fd4e35a8d4711d8552c92af300a3aa3d662fc3ec8e20ce68a4f69c38.jpeg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/04f0b5a446deb2c2e4ac7c5c301d7cbcae6ab2776b906e2ff20661dcbda4bdb0.jpeg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/b8113fd8a4cf5e50fd502452ab70da19cd7d5878a5f9f290574fb1aa6bdbe737.jpg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/e4840fd866aeea27686ccb514774043cf33d1e4883205ad69fd574d5c8c7551a.jpg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/b5925fb301b34f7c7f89f362d85cd721f32edf364247e72ee6c741aea93ccd99.jpeg","https://cdn.getyourguide.com/image/format=auto%2Cfit=crop%2Cgravity=auto%2Cquality=60%2Cwidth=385%2Cdpr=2/tour_img/ef6f364533457ac4e6ad3abcab002f6c081a29af3bf31ea4d844252868731888.jpeg"],"description":{"ar":"مارس السنوركل بين الشعاب المرجانية في محمية رأس محمد، أحد أفضل مواقع الغوص في العالم.","en":"Snorkel the coral reefs of Ras Mohammed National Park, one of the world's top dive sites.","ru":"Понырять с маской у коралловых рифов национального парка Рас-Мохаммед — одного из лучших дайв-сайтов мира.","de":"Schnorcheln Sie an den Korallenriffen des Ras-Mohammed-Nationalparks, einem der besten Tauchspots der Welt.","it":"Fai snorkeling tra le barriere coralline del Parco Nazionale di Ras Mohammed, uno dei migliori siti di immersione al mondo.","tr":"Dünyanın en iyi dalış noktalarından biri olan Ras Muhammed Milli Parkı'nın mercan resiflerinde şnorkel yapın."},"fullDescription":{"ar":"اقضِ يومًا كاملاً في استكشاف حدائق المرجان وجدران الشعاب المذهلة في محمية رأس محمد. يشمل معدات سنوركل كاملة وإحاطة عن الحياة البحرية وغداء على الشاطئ.","en":"Spend a full day exploring the coral gardens and dramatic reef walls of Ras Mohammed National Park. Includes full snorkeling gear, a marine-life briefing, and a beachside lunch. Suitable for beginners and experienced snorkelers alike.","ru":"Проведите целый день, исследуя коралловые сады и рифовые стены национального парка Рас-Мохаммед. В программе — снаряжение, инструктаж и обед на пляже.","de":"Verbringen Sie einen ganzen Tag mit der Erkundung der Korallengärten und Riffwände des Ras-Mohammed-Nationalparks. Inklusive Ausrüstung, Briefing und Strandmittagessen.","it":"Trascorri un'intera giornata esplorando i giardini di corallo e le pareti della barriera del Parco Nazionale di Ras Mohammed. Include attrezzatura, briefing e pranzo in spiaggia.","tr":"Ras Muhammed Milli Parkı'nın mercan bahçelerini ve resif duvarlarını keşfederek tam bir gün geçirin. Şnorkel ekipmanı, deniz canlıları brifingi ve sahilde öğle yemeği dahildir."},"includes":{"ar":["نقل من وإلى الفندق","معدات سنوركل","غداء ومشروبات غازية","رسوم دخول المحمية","مرشد يتحدث الإنجليزية"],"en":["Hotel pickup & drop-off","Snorkeling equipment","Lunch & soft drinks","National park entry fees","English-speaking guide"],"ru":["Трансфер от/до отеля","Снаряжение для снорклинга","Обед и напитки","Входные билеты в парк","Англоговорящий гид"],"de":["Hotelabholung & Rückfahrt","Schnorchelausrüstung","Mittagessen & Softdrinks","Eintritt Nationalpark","Englischsprachiger Guide"],"it":["Transfer da/per l'hotel","Attrezzatura da snorkeling","Pranzo e bibite","Biglietto d'ingresso al parco","Guida in inglese"],"tr":["Otelden alış-bırakış","Şnorkel ekipmanı","Öğle yemeği ve içecekler","Milli park giriş ücreti","İngilizce konuşan rehber"]},"meetingPoint":{"ar":"الاستلام من لوبي الفندق، ٧:٣٠ صباحًا","en":"Hotel lobby pickup, 7:30 AM","ru":"Встреча в лобби отеля, 7:30","de":"Abholung Hotellobby, 7:30 Uhr","it":"Ritiro in hotel, ore 7:30","tr":"Otel lobisinden alış, 07:30"},"excludes":{"ar":["المشروبات الكحولية","استئجار كاميرا تحت الماء","الإكراميات (اختياري)"],"en":["Alcoholic beverages","Underwater camera rental","Gratuities (optional)"],"ru":["Алкогольные напитки","Аренда подводной камеры","Чаевые (по желанию)"],"de":["Alkoholische Getränke","Unterwasserkamera-Verleih","Trinkgelder (optional)"],"it":["Bevande alcoliche","Noleggio fotocamera subacquea","Mance (facoltative)"],"tr":["Alkollü içecekler","Sualtı kamerası kiralama","Bahşiş (isteğe bağlı)"]},"whatToBring":{"ar":["ملابس سباحة","منشفة","واقي شمس","صندل مريح"],"en":["Swimsuit","Towel","Sunscreen","Comfortable sandals"],"ru":["Купальник","Полотенце","Солнцезащитный крем","Удобные сандалии"],"de":["Badeanzug","Handtuch","Sonnencreme","Bequeme Sandalen"],"it":["Costume da bagno","Asciugamano","Crema solare","Sandali comodi"],"tr":["Mayo","Havlu","Güneş kremi","Rahat sandalet"]},"itinerary":[{"time":"07:30","title":{"ar":"الاستلام من الفندق","en":"Hotel Pickup","ru":"Встреча в отеле","de":"Hotelabholung","it":"Ritiro in hotel","tr":"Otelden Alış"},"description":{"ar":"سيارتنا المكيّفة تستلمك من لوبي الفندق.","en":"Our air-conditioned vehicle collects you from your hotel lobby.","ru":"Наш кондиционируемый автомобиль заберёт вас из лобби отеля.","de":"Unser klimatisiertes Fahrzeug holt Sie von der Hotellobby ab.","it":"Il nostro veicolo climatizzato ti preleva dalla hall dell'hotel.","tr":"Klimalı aracımız sizi otel lobisinden alır."}},{"time":"09:00","title":{"ar":"الوصول والإحاطة","en":"Arrival & Briefing","ru":"Прибытие и инструктаж","de":"Ankunft & Briefing","it":"Arrivo e briefing","tr":"Varış ve Brifing"},"description":{"ar":"قابل مرشدك واحصل على إحاطة قصيرة عن السلامة والحياة البحرية قبل ارتداء المعدات.","en":"Meet your guide and get a short safety and marine-life briefing before gearing up.","ru":"Познакомьтесь с гидом и пройдите короткий инструктаж по безопасности перед экипировкой.","de":"Treffen Sie Ihren Guide und erhalten Sie ein kurzes Sicherheits-Briefing vor der Ausrüstung.","it":"Incontra la tua guida e ricevi un breve briefing sulla sicurezza prima di equipaggiarti.","tr":"Rehberinizle tanışın ve ekipman kuşanmadan önce kısa bir güvenlik brifingi alın."}},{"time":"09:30","title":{"ar":"محطة السنوركل الأولى","en":"First Snorkeling Stop","ru":"Первая остановка для снорклинга","de":"Erster Schnorchelstopp","it":"Prima tappa snorkeling","tr":"İlk Şnorkel Durağı"},"description":{"ar":"استكشف حدائق المرجان في موقع الشعاب الأول.","en":"Explore the coral gardens at the first reef site.","ru":"Исследуйте коралловые сады на первом рифе.","de":"Erkunden Sie die Korallengärten am ersten Riff.","it":"Esplora i giardini di corallo nel primo sito.","tr":"İlk resif noktasındaki mercan bahçelerini keşfedin."}},{"time":"12:00","title":{"ar":"غداء على الشاطئ","en":"Lunch on the Beach","ru":"Обед на пляже","de":"Mittagessen am Strand","it":"Pranzo in spiaggia","tr":"Sahilde Öğle Yemeği"},"description":{"ar":"استراحة غداء هادئة في بقعة شاطئية مظللة داخل المحمية.","en":"A relaxed lunch break at a shaded beach spot inside the park.","ru":"Спокойный обеденный перерыв в тенистом месте на пляже парка.","de":"Eine entspannte Mittagspause an einem schattigen Strandplatz im Park.","it":"Una pausa pranzo rilassante in un punto ombreggiato della spiaggia nel parco.","tr":"Park içinde gölgeli bir sahil noktasında rahat bir öğle yemeği molası."}},{"time":"13:00","title":{"ar":"محطة السنوركل الثانية","en":"Second Snorkeling Stop","ru":"Вторая остановка для снорклинга","de":"Zweiter Schnorchelstopp","it":"Seconda tappa snorkeling","tr":"İkinci Şnorkel Durağı"},"description":{"ar":"موقع شعاب ثانٍ بحياة بحرية مختلفة لاستكشافها.","en":"A second reef site with different marine life to explore.","ru":"Второй риф с иной морской живностью для изучения.","de":"Ein zweites Riff mit anderer Meereswelt zum Erkunden.","it":"Un secondo sito con una fauna marina diversa da esplorare.","tr":"Keşfedilecek farklı deniz canlılarına sahip ikinci bir resif noktası."}},{"time":"15:30","title":{"ar":"العودة إلى الفندق","en":"Return to Hotel","ru":"Возвращение в отель","de":"Rückfahrt zum Hotel","it":"Ritorno in hotel","tr":"Otele Dönüş"},"description":{"ar":"استرخِ في الطريق أثناء عودتك إلى فندقك.","en":"Relax on the drive back as we drop you at your hotel.","ru":"Отдохните по пути назад, пока мы довезём вас до отеля.","de":"Entspannen Sie sich auf der Rückfahrt zu Ihrem Hotel.","it":"Rilassati durante il tragitto di ritorno al tuo hotel.","tr":"Sizi otelinize bırakırken dönüş yolunda rahatlayın."}}],"owner":"BwomDIPc14TitJPZwdYjApde6Vy1"}$ds$::jsonb)
