insert into public.site_content (kind, id, sort_order, published, data) values ('destination', 'd1', 10, true, $ds${"id":"d1","name":{"en":"Ras Mohammed National Park","ar":"محمية رأس محمد","ru":"Национальный парк Рас-Мохаммед","de":"Ras-Mohammed-Nationalpark","it":"Parco Nazionale di Ras Mohammed","tr":"Ras Muhammed Milli Parkı"},"tagline":{"en":"Egypt's first and most famous marine national park","ar":"أول وأشهر محمية بحرية طبيعية في مصر","ru":"Первый и самый известный морской национальный парк Египта","de":"Ägyptens erster und bekanntester Meeresnationalpark","it":"Il primo e più famoso parco nazionale marino d'Egitto","tr":"Mısır'ın ilk ve en ünlü deniz milli parkı"},"description":{"en":"A protected national park south of Sharm El Sheikh, famed for sheer coral reef walls and rich marine life.","ar":"محمية طبيعية محمية جنوب شرم الشيخ، تشتهر بجدرانها المرجانية الرأسية وحياتها البحرية الغنية.","ru":"Заповедный национальный парк к югу от Шарм-эль-Шейха, известный отвесными коралловыми рифами и богатой морской жизнью.","de":"Ein geschützter Nationalpark südlich von Sharm El Sheikh, bekannt für steile Korallenriffwände und reiches Meeresleben.","it":"Un parco nazionale protetto a sud di Sharm El Sheikh, famoso per le pareti coralline a strapiombo e la ricca vita marina.","tr":"Sharm El Sheikh'in güneyinde, dik mercan resif duvarları ve zengin deniz yaşamıyla ünlü korunan bir milli park."},"fullDescription":{"en":"Established in 1983 as Egypt's first national park, Ras Mohammed sits at the southern tip of the Sinai Peninsula where the Gulf of Aqaba meets the Gulf of Suez. It is widely regarded as one of the world's top diving and snorkeling destinations, known for dramatic reef walls, mangrove channels, and abundant marine biodiversity.","ar":"تأسست محمية رأس محمد عام ١٩٨٣ لتكون أول محمية طبيعية في مصر، وتقع عند الطرف الجنوبي لشبه جزيرة سيناء حيث يلتقي خليج العقبة بخليج السويس. تُعد من أبرز وجهات الغوص والسنوركل في العالم، وتشتهر بجدرانها المرجانية شديدة الانحدار وقنوات المانجروف وتنوعها البحري الثري.","ru":"Основанный в 1983 году как первый национальный парк Египта, Рас-Мохаммед расположен на южной оконечности Синайского полуострова, где Акабский залив встречается с Суэцким. Считается одним из лучших в мире мест для дайвинга и снорклинга благодаря отвесным рифовым стенам и богатому биоразнообразию.","de":"1983 als Ägyptens erster Nationalpark gegründet, liegt Ras Mohammed an der Südspitze der Sinai-Halbinsel, wo der Golf von Akaba auf den Golf von Suez trifft. Er gilt als eines der weltweit besten Tauch- und Schnorchelziele mit steilen Riffwänden und reicher Artenvielfalt.","it":"Istituito nel 1983 come primo parco nazionale d'Egitto, Ras Mohammed si trova all'estremità meridionale della penisola del Sinai, dove il Golfo di Aqaba incontra il Golfo di Suez. È considerato una delle migliori destinazioni al mondo per immersioni e snorkeling grazie alle pareti coralline a strapiombo e alla ricca biodiversità marina.","tr":"1983 yılında Mısır'ın ilk milli parkı olarak kurulan Ras Muhammed, Akabe Körfezi'nin Süveyş Körfezi ile buluştuğu Sina Yarımadası'nın güney ucunda yer alır. Dik resif duvarları ve zengin deniz biyoçeşitliliğiyle dünyanın en iyi dalış ve şnorkel noktalarından biri olarak kabul edilir."},"location":{"en":"South Sinai, south of Sharm El Sheikh","ar":"جنوب سيناء، جنوب شرم الشيخ","ru":"Южный Синай, к югу от Шарм-эль-Шейха","de":"Süd-Sinai, südlich von Sharm El Sheikh","it":"Sinai del Sud, a sud di Sharm El Sheikh","tr":"Güney Sina, Sharm El Sheikh'in güneyi"},"rating":4.8,"review_count":3932,"coordinates":{"lat":27.7937578,"lng":34.1780397},"phone":"+20 69 3660559","google_place_id":"ChIJjaZakvEjUxQRRZNUw4HthtI","google_maps_url":"https://www.google.com/maps/place/?q=place_id:ChIJjaZakvEjUxQRRZNUw4HthtI","image":"https://egyptra.pro/uploads/photo_library/photo_67ac8aa74e42f.jpg","images":["https://www.egyptpromotion.com/uploads/tour/1635335506full-day-ras-mohammed-national-park-day-trip-by-boat-02.jpg","https://egyptra.pro/uploads/photo_library/photo_67ac8aa74e42f.jpg","https://media.tacdn.com/media/attractions-splice-spp-674x446/0b/c8/1d/16.jpg","https://q-xx.bstatic.com/xdata/images/xphoto/900x600/198969815.jpg?k=afc80abb739cbed3c25955a33706fca256227a2e06416af733fe9e9e14cd5cea&o=","https://www.shoreexcursionsgroup.com/img/tour/EUSSRMSNRKL-2.jpg","https://egypt-snorkeling.com/trips/sharm-el-sheikh/ras-mohamed-national-park/5.webp","https://dynamic-media-cdn.tripadvisor.com/media/photo-o/33/18/41/f7/caption.jpg?w=1200&h=-1&s=1","https://onetour-egypt.ru/wp-content/uploads/2024/05/sea-trip.jpg"]}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('destination', 'd2', 20, true, $ds${"id":"d2","name":{"en":"Naama Bay","ar":"خليج نعمة","ru":"Наама Бэй","de":"Naama Bay","it":"Naama Bay","tr":"Naama Bay"},"tagline":{"en":"The lively tourist heart of Sharm El Sheikh","ar":"القلب السياحي النابض بالحياة في شرم الشيخ","ru":"Оживлённое туристическое сердце Шарм-эль-Шейха","de":"Das lebendige touristische Herz von Sharm El Sheikh","it":"Il vivace cuore turistico di Sharm El Sheikh","tr":"Sharm El Sheikh'in hareketli turizm merkezi"},"description":{"en":"A beachfront promenade lined with hotels, restaurants, cafes and shops in the center of Sharm El Sheikh.","ar":"ممشى ساحلي يضم الفنادق والمطاعم والمقاهي والمحلات في وسط شرم الشيخ.","ru":"Прибрежный променад с отелями, ресторанами, кафе и магазинами в центре Шарм-эль-Шейха.","de":"Eine Strandpromenade mit Hotels, Restaurants, Cafés und Geschäften im Zentrum von Sharm El Sheikh.","it":"Un lungomare fiancheggiato da hotel, ristoranti, caffè e negozi nel centro di Sharm El Sheikh.","tr":"Sharm El Sheikh'in merkezinde oteller, restoranlar, kafeler ve mağazalarla çevrili bir sahil yürüyüş yolu."},"fullDescription":{"en":"Naama Bay is the main tourist hub of Sharm El Sheikh, centered on a pedestrian beachfront promenade. It combines sandy beaches and calm swimming waters with a dense concentration of hotels, international restaurants, cafes, shops and water-sports operators, and is especially lively in the evenings.","ar":"يُعد خليج نعمة المركز السياحي الرئيسي في شرم الشيخ، ويتمحور حول ممشى ساحلي مخصص للمشاة. يجمع بين الشواطئ الرملية ومياه السباحة الهادئة وتركز كثيف للفنادق والمطاعم العالمية والمقاهي والمحلات ومشغلي الرياضات المائية، وتزداد حيويته بشكل خاص في المساء.","ru":"Наама Бэй — главный туристический центр Шарм-эль-Шейха, сосредоточенный вокруг пешеходной набережной. Здесь сочетаются песчаные пляжи со спокойной водой и плотная концентрация отелей, международных ресторанов, кафе, магазинов и операторов водных видов спорта; особенно оживлённо по вечерам.","de":"Naama Bay ist das touristische Zentrum von Sharm El Sheikh und dreht sich um eine Fußgänger-Strandpromenade. Sandstrände und ruhiges Wasser treffen hier auf eine hohe Dichte an Hotels, internationalen Restaurants, Cafés, Geschäften und Wassersportanbietern; abends besonders lebendig.","it":"Naama Bay è il principale centro turistico di Sharm El Sheikh, incentrato su un lungomare pedonale. Unisce spiagge sabbiose e acque calme a un'alta concentrazione di hotel, ristoranti internazionali, caffè, negozi e operatori di sport acquatici, particolarmente vivace la sera.","tr":"Naama Bay, yaya sahil yürüyüş yoluna dayanan Sharm El Sheikh'in ana turizm merkezidir. Kumlu plajlar ve sakin sularla birlikte yoğun otel, uluslararası restoran, kafe, mağaza ve su sporları işletmeleri barındırır; özellikle akşamları çok canlıdır."},"location":{"en":"Central Sharm El Sheikh","ar":"وسط شرم الشيخ","ru":"Центр Шарм-эль-Шейха","de":"Zentrum von Sharm El Sheikh","it":"Centro di Sharm El Sheikh","tr":"Sharm El Sheikh Merkezi"},"rating":4.5,"review_count":3690,"coordinates":{"lat":27.9116973,"lng":34.3324244},"phone":"","google_place_id":"ChIJi2edSoc3UxQR0CSgCn6HllE","google_maps_url":"https://www.google.com/maps/place/?q=place_id:ChIJi2edSoc3UxQR0CSgCn6HllE","image":"","images":[]}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('destination', 'd3', 30, true, $ds${"id":"d3","name":{"en":"Farsha Cafe","ar":"كافيه فرشة","ru":"Кафе Фарша","de":"Farsha Cafe","it":"Farsha Cafe","tr":"Farsha Cafe"},"tagline":{"en":"An iconic Bedouin-style cliffside lounge","ar":"مقهى جبلي بطراز بدوي أيقوني","ru":"Культовое кафе в бедуинском стиле на скале","de":"Ein ikonisches Bedouinen-Café an der Klippe","it":"Un iconico locale beduino sulla scogliera","tr":"Kayalıkta ikonik Bedevi tarzı kafe"},"description":{"en":"A well-known Bedouin-style cafe and lounge built on the cliffside at Hadaba, overlooking the sea.","ar":"مقهى ولاونج معروف بطراز بدوي، مبني على حافة هضبة أم السيد مطلاً على البحر.","ru":"Известное кафе-лаунж в бедуинском стиле, построенное на скале в районе Хадаба с видом на море.","de":"Ein bekanntes Café und Lounge im Beduinenstil, das auf der Klippe von Hadaba mit Meerblick errichtet wurde.","it":"Un noto caffè-lounge in stile beduino, costruito sulla scogliera di Hadaba con vista sul mare.","tr":"Hadaba'daki kayalık üzerine deniz manzaralı olarak inşa edilmiş, tanınmış Bedevi tarzı bir kafe ve lounge."},"fullDescription":{"en":"Located in the Hadaba (Ras Um Sid) district, Farsha Cafe is one of the most photographed spots in Sharm El Sheikh, known for its traditional floor cushions, lanterns, and terraced seating carved into the cliff. It draws large crowds especially around sunset, and note that it operates on a walk-in, no-reservation basis.","ar":"يقع كافيه فرشة في منطقة الهضبة (رأس أم السيد)، وهو من أكثر الأماكن تصويرًا في شرم الشيخ، ويشتهر بوسائده الأرضية التقليدية وفوانينه ومقاعده المتدرجة المنحوتة في الصخر. يستقطب أعدادًا كبيرة من الزوار خاصة عند الغروب، مع العلم أنه لا يقبل الحجز المسبق ويعتمد على الدخول المباشر فقط.","ru":"Расположенное в районе Хадаба (Рас-Умм-Сид), кафе Фарша — одно из самых фотографируемых мест в Шарм-эль-Шейхе, известное традиционными напольными подушками, фонарями и террасными сиденьями, вырезанными в скале. Особенно многолюдно на закате; бронирование не предусмотрено, вход только по живой очереди.","de":"Im Stadtteil Hadaba (Ras Um Sid) gelegen, ist das Farsha Cafe einer der meistfotografierten Orte in Sharm El Sheikh, bekannt für traditionelle Bodenkissen, Laternen und terrassenförmige, in den Felsen gehauene Sitzplätze. Besonders bei Sonnenuntergang sehr belebt; es gibt keine Reservierung, nur Einlass nach Wartereihenfolge.","it":"Situato nel quartiere di Hadaba (Ras Um Sid), il Farsha Cafe è uno dei luoghi più fotografati di Sharm El Sheikh, noto per i cuscini tradizionali a terra, le lanterne e i posti a sedere a terrazza scavati nella roccia. Molto affollato soprattutto al tramonto; non si accettano prenotazioni, solo ingresso diretto.","tr":"Hadaba (Ras Um Sid) bölgesinde yer alan Farsha Cafe, geleneksel yer minderleri, fenerler ve kayalığa oyulmuş teraslı oturma alanlarıyla tanınan, Sharm El Sheikh'in en çok fotoğraflanan yerlerinden biridir. Özellikle gün batımında çok kalabalık olur; rezervasyon kabul edilmez, yalnızca sırayla giriş yapılır."},"location":{"en":"Hadaba (Ras Um Sid), Sharm El Sheikh","ar":"هضبة أم السيد، شرم الشيخ","ru":"Хадаба (Рас-Умм-Сид), Шарм-эль-Шейх","de":"Hadaba (Ras Um Sid), Sharm El Sheikh","it":"Hadaba (Ras Um Sid), Sharm El Sheikh","tr":"Hadaba (Ras Um Sid), Sharm El Sheikh"},"rating":4.2,"review_count":23351,"coordinates":{"lat":27.8496792,"lng":34.3075904},"phone":"+20 12 00300162","google_place_id":"ChIJnSTrOz46UxQRUCvBd_dzKWU","google_maps_url":"https://www.google.com/maps/place/?q=place_id:ChIJnSTrOz46UxQRUCvBd_dzKWU","image":"","images":[]}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('destination', 'd4', 40, true, $ds${"id":"d4","name":{"en":"Al-Sahaba Mosque","ar":"مسجد الصحابة","ru":"Мечеть Аль-Сахаба","de":"Al-Sahaba-Moschee","it":"Moschea Al-Sahaba","tr":"Sahabe Camii"},"tagline":{"en":"A landmark mosque in the heart of the Old Market","ar":"معلم بارز في قلب السوق القديم","ru":"Знаковая мечеть в самом сердце Старого рынка","de":"Eine markante Moschee im Herzen des Alten Marktes","it":"Una moschea di riferimento nel cuore del Vecchio Mercato","tr":"Eski Çarşı'nın kalbinde simge bir cami"},"description":{"en":"A large, richly decorated mosque standing at the center of the Old Market, free to visit outside prayer times.","ar":"مسجد كبير وغني بالزخارف يتوسط السوق القديم، ويمكن زيارته مجانًا خارج أوقات الصلاة.","ru":"Большая, богато украшенная мечеть в центре Старого рынка, вход свободный вне часов молитвы.","de":"Eine große, reich verzierte Moschee im Zentrum des Alten Marktes, außerhalb der Gebetszeiten kostenlos zu besichtigen.","it":"Una grande moschea riccamente decorata nel cuore del Vecchio Mercato, visitabile gratuitamente al di fuori degli orari di preghiera.","tr":"Eski Çarşı'nın merkezinde yer alan, zengin süslemelere sahip büyük bir cami; namaz vakitleri dışında ücretsiz ziyaret edilebilir."},"fullDescription":{"en":"Al-Sahaba Mosque stands at the center of Sharm El Sheikh's Old Market and is considered one of the city's architectural landmarks, featuring twin minarets and detailed stonework. Visitors are welcome outside prayer times, and modest dress (including a headscarf and full-length garment for women, available on site) is required.","ar":"يتوسط مسجد الصحابة السوق القديم في شرم الشيخ، ويُعد من أبرز معالمها المعمارية بمئذنتيه التوأم وزخارفه الحجرية الدقيقة. يُرحَّب بالزوار خارج أوقات الصلاة، ويُشترط ارتداء زي محتشم (يشمل غطاء رأس وثوب طويل للسيدات، متوفر في الموقع).","ru":"Мечеть Аль-Сахаба расположена в центре Старого рынка Шарм-эль-Шейха и считается одной из архитектурных достопримечательностей города благодаря двум минаретам и детальной каменной резьбе. Посетителей принимают вне часов молитвы; требуется скромная одежда (для женщин — платок и длинное платье, доступны на месте).","de":"Die Al-Sahaba-Moschee steht im Zentrum des Alten Marktes von Sharm El Sheikh und gilt mit ihren zwei Minaretten und detaillierten Steinmetzarbeiten als architektonisches Wahrzeichen der Stadt. Besucher sind außerhalb der Gebetszeiten willkommen; angemessene Kleidung (für Frauen Kopftuch und langes Gewand, vor Ort erhältlich) ist erforderlich.","it":"La Moschea Al-Sahaba sorge al centro del Vecchio Mercato di Sharm El Sheikh ed è considerata uno dei simboli architettonici della città, con due minareti gemelli e intagli in pietra dettagliati. I visitatori sono benvenuti al di fuori degli orari di preghiera; è richiesto un abbigliamento modesto (per le donne velo e abito lungo, disponibili sul posto).","tr":"Sahabe Camii, Sharm El Sheikh'in Eski Çarşısının merkezinde yer alır ve ikiz minareleri ile ayrıntılı taş işçiliğiyle şehrin mimari simgelerinden biri kabul edilir. Ziyaretçiler namaz vakitleri dışında kabul edilir; tesiste sağlanan başörtüsü ve uzun elbise dahil olmak üzere mütevazı kıyafet gereklidir."},"location":{"en":"Old Market, Sharm El Sheikh","ar":"السوق القديم، شرم الشيخ","ru":"Старый рынок, Шарм-эль-Шейх","de":"Alter Markt, Sharm El Sheikh","it":"Vecchio Mercato, Sharm El Sheikh","tr":"Eski Çarşı, Sharm El Sheikh"},"rating":4.8,"review_count":4513,"coordinates":{"lat":27.8664178,"lng":34.2952438},"phone":"","google_place_id":"ChIJSVTNrS86UxQRsvjUALKtRF0","google_maps_url":"https://www.google.com/maps/place/?q=place_id:ChIJSVTNrS86UxQRsvjUALKtRF0","image":"","images":[]}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('destination', 'd5', 50, true, $ds${"id":"d5","name":{"en":"Old Market (Souk)","ar":"السوق القديم","ru":"Старый рынок (Сук)","de":"Alter Markt (Souk)","it":"Vecchio Mercato (Souk)","tr":"Eski Çarşı (Sûk)"},"tagline":{"en":"Traditional Egyptian shopping and seafood dining","ar":"التسوق التقليدي والمأكولات البحرية الأصيلة","ru":"Традиционный базар и рестораны морепродуктов","de":"Traditionelles ägyptisches Einkaufen und Fischrestaurants","it":"Shopping tradizionale egiziano e ristoranti di pesce","tr":"Geleneksel Mısır alışverişi ve deniz ürünleri restoranları"},"description":{"en":"A lively bazaar with spice shops, souvenir stalls and seafood restaurants, busiest in the evening.","ar":"سوق شعبي نابض بالحياة يضم محلات التوابل ومحلات الهدايا ومطاعم المأكولات البحرية، وأكثر ازدحامًا في المساء.","ru":"Оживлённый базар с лавками специй, сувенирными киосками и рыбными ресторанами, наиболее людный вечером.","de":"Ein belebter Basar mit Gewürzläden, Souvenirständen und Fischrestaurants, abends am geschäftigsten.","it":"Un vivace bazar con negozi di spezie, bancarelle di souvenir e ristoranti di pesce, più frequentato la sera.","tr":"Baharat dükkanları, hediyelik eşya standları ve deniz ürünleri restoranlarıyla dolu, akşamları en yoğun olan canlı bir pazar."},"fullDescription":{"en":"The Old Market is Sharm El Sheikh's traditional bazaar district, home to Al-Sahaba Mosque and dozens of shops selling spices, textiles, leather goods and souvenirs, alongside popular seafood restaurants where fish is chosen fresh and cooked to order. Prices are generally negotiable and the area comes alive after sunset.","ar":"يُعد السوق القديم الحي التجاري التقليدي في شرم الشيخ، ويضم مسجد الصحابة وعشرات المحلات التي تبيع التوابل والمنسوجات والمنتجات الجلدية والهدايا التذكارية، إلى جانب مطاعم مأكولات بحرية شهيرة يختار فيها الزبون السمك طازجًا ليُطهى حسب الطلب. الأسعار قابلة للتفاوض عمومًا، وتنشط المنطقة بشكل خاص بعد غروب الشمس.","ru":"Старый рынок — традиционный торговый квартал Шарм-эль-Шейха, где находится мечеть Аль-Сахаба и десятки лавок со специями, тканями, кожаными изделиями и сувенирами, а также популярные рыбные рестораны, где рыбу выбирают свежей и готовят на заказ. Цены обычно можно обсуждать, а район особенно оживает после заката.","de":"Der Alte Markt ist das traditionelle Basarviertel von Sharm El Sheikh mit der Al-Sahaba-Moschee und Dutzenden Geschäften für Gewürze, Textilien, Lederwaren und Souvenirs sowie beliebten Fischrestaurants, in denen der Fisch frisch ausgewählt und nach Wunsch zubereitet wird. Preise sind meist verhandelbar, das Viertel belebt sich besonders nach Sonnenuntergang.","it":"Il Vecchio Mercato è il quartiere del bazar tradizionale di Sharm El Sheikh, sede della Moschea Al-Sahaba e di decine di negozi di spezie, tessuti, articoli in pelle e souvenir, oltre a rinomati ristoranti di pesce dove il pesce viene scelto fresco e cucinato su richiesta. I prezzi sono generalmente negoziabili e la zona si anima soprattutto dopo il tramonto.","tr":"Eski Çarşı, Sahabe Camii'ne ev sahipliği yapan ve baharat, tekstil, deri ürünleri ve hediyelik eşya satan onlarca dükkanın yanı sıra balığın taze seçilip sipariş üzerine pişirildiği popüler deniz ürünleri restoranlarının bulunduğu Sharm El Sheikh'in geleneksel çarşı bölgesidir. Fiyatlar genellikle pazarlığa açıktır ve bölge özellikle gün batımından sonra canlanır."},"location":{"en":"Old Town, Sharm El Sheikh","ar":"المدينة القديمة، شرم الشيخ","ru":"Старый город, Шарм-эль-Шейх","de":"Altstadt, Sharm El Sheikh","it":"Città Vecchia, Sharm El Sheikh","tr":"Eski Şehir, Sharm El Sheikh"},"rating":4.4,"review_count":42402,"coordinates":{"lat":27.8655516,"lng":34.294171},"phone":"+20 10 18683119","google_place_id":"ChIJa-E1Hy46UxQRRJIer96S6Qo","google_maps_url":"https://www.google.com/maps/place/?q=place_id:ChIJa-E1Hy46UxQRRJIer96S6Qo","image":"","images":[]}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('destination', 'd6', 60, true, $ds${"id":"d6","name":{"en":"SOHO Square","ar":"سوهو سكوير","ru":"SOHO Square","de":"SOHO Square","it":"SOHO Square","tr":"SOHO Square"},"tagline":{"en":"Modern entertainment, dining and shows","ar":"مركز ترفيهي حديث للعروض والمطاعم والتسوق","ru":"Современные развлечения, рестораны и шоу","de":"Moderne Unterhaltung, Gastronomie und Shows","it":"Intrattenimento moderno, ristoranti e spettacoli","tr":"Modern eğlence, restoranlar ve gösteriler"},"description":{"en":"A pedestrian entertainment complex with a dancing fountain, ice rink and international restaurants.","ar":"مجمع ترفيهي للمشاة يضم نافورة راقصة وصالة تزلج على الجليد ومطاعم عالمية.","ru":"Пешеходный развлекательный комплекс с танцующим фонтаном, катком и международными ресторанами.","de":"Ein Fußgänger-Unterhaltungskomplex mit Musikbrunnen, Eisbahn und internationalen Restaurants.","it":"Un complesso pedonale per lo svago con fontana danzante, pista di pattinaggio e ristoranti internazionali.","tr":"Dans eden fıskiyesi, buz pateni pisti ve uluslararası restoranlarıyla yaya eğlence kompleksi."},"fullDescription":{"en":"SOHO Square is a pedestrian-only entertainment complex in Sharm El Sheikh featuring a musical dancing fountain, an ice-skating rink, shops, and a wide range of restaurants and cafes. It is particularly popular in the evening when the fountain and lighting displays are active.","ar":"سوهو سكوير مجمع ترفيهي مخصص للمشاة في شرم الشيخ، يضم نافورة موسيقية راقصة، صالة تزلج على الجليد، محلات تجارية، ومجموعة واسعة من المطاعم والمقاهي. يحظى بشعبية خاصة في المساء عندما تعمل النافورة وعروض الإضاءة.","ru":"SOHO Square — пешеходный развлекательный комплекс в Шарм-эль-Шейхе с музыкальным танцующим фонтаном, катком, магазинами и широким выбором ресторанов и кафе. Особенно популярен вечером, когда работают фонтан и световые шоу.","de":"SOHO Square ist ein reiner Fußgänger-Unterhaltungskomplex in Sharm El Sheikh mit einem musikalischen Tanzbrunnen, einer Eisbahn, Geschäften und einer breiten Auswahl an Restaurants und Cafés. Besonders beliebt am Abend, wenn Brunnen- und Lichtshows laufen.","it":"SOHO Square è un complesso pedonale per lo svago a Sharm El Sheikh con una fontana musicale danzante, una pista di pattinaggio, negozi e un'ampia gamma di ristoranti e caffè. Particolarmente popolare la sera, quando sono attivi la fontana e gli spettacoli di luci.","tr":"SOHO Square, Sharm El Sheikh'te yalnızca yayalara açık; müzikli dans eden fıskiyesi, buz pateni pisti, mağazaları ve geniş restoran-kafe seçenekleriyle bir eğlence kompleksidir. Fıskiye ve ışık gösterilerinin etkin olduğu akşamları özellikle popülerdir."},"location":{"en":"Sharks Bay area, Sharm El Sheikh","ar":"منطقة خليج شارك باي، شرم الشيخ","ru":"Район Шаркс-Бэй, Шарм-эль-Шейх","de":"Sharks-Bay-Gebiet, Sharm El Sheikh","it":"Zona Sharks Bay, Sharm El Sheikh","tr":"Sharks Bay bölgesi, Sharm El Sheikh"},"rating":4.5,"review_count":45117,"coordinates":{"lat":27.9624931,"lng":34.3937437},"phone":"+20 10 00109109","google_place_id":"ChIJ-SUwp5hJUxQR13GK4yhFy-Q","google_maps_url":"https://www.google.com/maps/place/?q=place_id:ChIJ-SUwp5hJUxQR13GK4yhFy-Q","image":"","images":[]}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('article', 'a1', 10, true, $ds${"id":"a1","title":{"en":"5 Best Snorkeling Spots Near Sharm El Sheikh","ar":"أفضل ٥ أماكن للسنوركل قرب شرم الشيخ","ru":"5 лучших мест для снорклинга рядом с Шарм-эль-Шейхом","de":"Die 5 besten Schnorchel-Spots bei Sharm El Sheikh","it":"I 5 migliori spot per lo snorkeling vicino a Sharm El Sheikh","tr":"Sharm El Sheikh Yakınındaki En İyi 5 Şnorkel Noktası"},"excerpt":{"en":"From Ras Mohammed's coral walls to the calm shallows of Naama Bay — where to see the Red Sea's best reefs.","ar":"من جدران المرجان في رأس محمد إلى المياه الهادئة في خليج نعمة — أين ترى أفضل شعاب البحر الأحمر.","ru":"От коралловых стен Рас-Мохаммеда до спокойных мелководий Наама Бэй — где увидеть лучшие рифы Красного моря.","de":"Von den Korallenwänden von Ras Mohammed bis zu den ruhigen Untiefen von Naama Bay — wo man die besten Riffe des Roten Meeres sieht.","it":"Dalle pareti coralline di Ras Mohammed alle acque basse e calme di Naama Bay — dove vedere le migliori barriere del Mar Rosso.","tr":"Ras Muhammed'in mercan duvarlarından Naama Bay'in sakin sığ sularına — Kızıldeniz'in en iyi resiflerini nerede görebilirsiniz."},"content":{"en":"The waters around Sharm El Sheikh are consistently ranked among the world's best for snorkeling, thanks to warm, clear water and reefs that start just meters from shore. Ras Mohammed National Park tops most lists — its sheer coral walls drop straight into deep blue and host everything from reef sharks to sea turtles. Closer to town, Naama Bay offers calmer, shallower water that's ideal for first-timers and families. Tiran Island, reachable only by boat, rewards the trip with some of the region's healthiest coral gardens. Ras Um Sid is a local favorite for its house reef right off the beach, while Shark's Bay lets you walk straight in from the sand. Whichever spot you choose, go early in the day for the calmest water and best visibility, and always ask your guide about current conditions before entering.","ar":"تُصنَّف مياه شرم الشيخ باستمرار من بين الأفضل في العالم للسنوركل، بفضل مياهها الدافئة الصافية وشعابها التي تبدأ على بُعد أمتار من الشاطئ. تتصدر محمية رأس محمد معظم القوائم — جدرانها المرجانية الحادة تنحدر مباشرة إلى الأزرق العميق وتستضيف كل شيء من أسماك القرش الشعبية إلى السلاحف البحرية. وبالقرب من المدينة، يوفر خليج نعمة مياهً أكثر هدوءًا وضحالة مثالية للمبتدئين والعائلات. جزيرة تيران، التي لا يمكن الوصول إليها إلا بالقارب، تكافئ الرحلة بحدائق مرجانية من أصح ما في المنطقة. رأس أم سيد مفضل محلي بفضل شعابه المنزلية القريبة من الشاطئ مباشرة، بينما يتيح لك خليج القرش الدخول مباشرة من الرمال. أيًا كان المكان الذي تختاره، اذهب في وقت مبكر من اليوم لأهدأ مياه وأفضل رؤية، واسأل مرشدك دائمًا عن حالة التيار قبل الدخول.","ru":"Воды вокруг Шарм-эль-Шейха неизменно входят в число лучших в мире для снорклинга благодаря тёплой прозрачной воде и рифам, начинающимся всего в нескольких метрах от берега. Национальный парк Рас-Мохаммед возглавляет большинство списков — его отвесные коралловые стены уходят прямо в глубокую синеву. Ближе к городу Наама Бэй предлагает более спокойную и мелкую воду, идеальную для новичков и семей. Остров Тиран, куда можно добраться только на лодке, вознаграждает поездку одними из самых здоровых коралловых садов региона.","de":"Die Gewässer um Sharm El Sheikh gehören durchweg zu den besten der Welt zum Schnorcheln, dank warmen, klaren Wassers und Riffen, die nur wenige Meter vom Ufer entfernt beginnen. Der Ras-Mohammed-Nationalpark führt die meisten Listen an — seine steilen Korallenwände fallen direkt ins tiefe Blau ab. Näher an der Stadt bietet Naama Bay ruhigeres, flacheres Wasser, ideal für Anfänger und Familien.","it":"Le acque intorno a Sharm El Sheikh sono costantemente classificate tra le migliori al mondo per lo snorkeling, grazie ad acque calde e limpide e barriere che iniziano a pochi metri dalla riva. Il Parco Nazionale di Ras Mohammed è in cima alla maggior parte delle liste — le sue pareti coralline a strapiombo scendono direttamente nel blu profondo. Più vicino alla città, Naama Bay offre acque più calme e basse, ideali per principianti e famiglie.","tr":"Sharm El Sheikh çevresindeki sular, sıcak ve berrak suyu ile kıyıdan sadece birkaç metre uzaklıkta başlayan resifleri sayesinde dünyanın en iyi şnorkel noktaları arasında sürekli yer alır. Ras Muhammed Milli Parkı çoğu listenin başında gelir — dik mercan duvarları doğrudan derin maviye iner. Şehre daha yakın olan Naama Bay, yeni başlayanlar ve aileler için ideal, daha sakin ve sığ sular sunar."},"image":"https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=900&q=85","author":"Discover Sharm Editorial","readTimeMinutes":4}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('article', 'a2', 20, true, $ds${"id":"a2","title":{"en":"A First-Timer's Guide to the White Desert Safari","ar":"دليل أول مرة لرحلة سفاري الصحراء البيضاء","ru":"Гид новичка по сафари в Белой пустыне","de":"Ein Leitfaden für Einsteiger zur Wüstensafari","it":"Guida per principianti al Safari nel Deserto Bianco","tr":"Beyaz Çöl Safarisi İçin Yeni Başlayan Rehberi"},"excerpt":{"en":"What to wear, what to expect, and why the ride home under the stars is the best part.","ar":"ماذا ترتدي، وماذا تتوقع، ولماذا تكون رحلة العودة تحت النجوم أفضل جزء.","ru":"Что надеть, чего ожидать и почему поездка домой под звёздами — лучшая часть.","de":"Was man anziehen sollte, was einen erwartet und warum die Heimfahrt unter den Sternen der beste Teil ist.","it":"Cosa indossare, cosa aspettarsi e perché il viaggio di ritorno sotto le stelle è la parte migliore.","tr":"Ne giymeli, ne beklemeli ve neden yıldızların altında eve dönüş en güzel kısım."},"content":{"en":"A desert safari is one of the most popular half-day trips out of Sharm, and for good reason — it packs quad biking, a camel ride, Bedouin hospitality and a BBQ dinner under an genuinely dark sky into a single evening. Wear closed shoes and clothes you don't mind getting dusty; a light jacket helps once the sun goes down and the desert cools fast. Quad bikes are usually shared two-to-a-bike and don't require a license, but do require a signed waiver and a briefing — listen closely, the sand can be softer than it looks. The Bedouin tea stop is a highlight for many guests: you'll sit on carpets in a traditional tent while your hosts prepare sweet tea over an open fire. Dinner is typically grilled chicken or kofta with rice and salads, and the trip usually wraps with a short stargazing session — in the open desert, away from city lights, the Milky Way is often clearly visible.","ar":"تُعد رحلة السفاري الصحراوية واحدة من أكثر رحلات نصف اليوم شعبية خارج شرم الشيخ، ولسبب وجيه — فهي تجمع بين قيادة الدراجات الرباعية وركوب الجمال والضيافة البدوية وعشاء الشواء تحت سماء مظلمة حقًا في أمسية واحدة. ارتدِ أحذية مغلقة وملابس لا تمانع في اتساخها بالغبار؛ سترة خفيفة تساعد بمجرد غروب الشمس وبرودة الصحراء السريعة. تُقاد الدراجات الرباعية عادة بواقع شخصين لكل دراجة ولا تتطلب رخصة، لكنها تتطلب توقيع إقرار وإحاطة — استمع جيدًا، فالرمال قد تكون أنعم مما تبدو. تُعد محطة الشاي البدوي من أبرز اللحظات لكثير من الضيوف: ستجلس على سجاد في خيمة تقليدية بينما يُعِدّ مضيفوك الشاي المُحلّى على نار مفتوحة.","ru":"Пустынное сафари — одна из самых популярных поездок на полдня из Шарма, и не зря — она объединяет катание на квадроциклах, поездку на верблюде, бедуинское гостеприимство и ужин-барбекю под по-настоящему тёмным небом в один вечер. Наденьте закрытую обувь и одежду, которую не жаль испачкать пылью.","de":"Eine Wüstensafari ist einer der beliebtesten Halbtagesausflüge ab Sharm, und das aus gutem Grund — sie vereint Quad-Biking, eine Kamelfahrt, beduinische Gastfreundschaft und ein BBQ-Dinner unter einem wirklich dunklen Himmel an einem einzigen Abend. Tragen Sie geschlossene Schuhe und Kleidung, die staubig werden darf.","it":"Un safari nel deserto è una delle gite di mezza giornata più popolari da Sharm, e con buona ragione — racchiude quad, un giro in cammello, ospitalità beduina e una cena BBQ sotto un cielo davvero buio in un'unica serata. Indossa scarpe chiuse e abiti che non ti dispiace impolverare.","tr":"Çöl safarisi, Sharm'dan yapılan en popüler yarım günlük gezilerden biridir ve bunun iyi bir nedeni vardır — tek bir akşamda ATV sürüşü, deve gezisi, Bedevi misafirperverliği ve gerçekten karanlık bir gökyüzü altında barbekü yemeğini bir araya getirir. Kapalı ayakkabılar ve tozlanmasına aldırmadığınız kıyafetler giyin."},"image":"https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=900&q=85","author":"Discover Sharm Editorial","readTimeMinutes":5}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('article', 'a3', 30, true, $ds${"id":"a3","title":{"en":"Where to Eat in Sharm: A Local's Food Guide","ar":"أين تأكل في شرم الشيخ: دليل الطعام المحلي","ru":"Где поесть в Шарме: гид по еде от местных","de":"Wo man in Sharm essen kann: Ein lokaler Food-Guide","it":"Dove mangiare a Sharm: guida gastronomica locale","tr":"Sharm'da Nerede Yenir: Yerel Yemek Rehberi"},"excerpt":{"en":"From Old Market street food to a sunset seafood splurge — a quick tour of where residents actually eat.","ar":"من طعام الشارع في السوق القديم إلى وليمة مأكولات بحرية عند الغروب — جولة سريعة على أماكن أكل السكان الفعلية.","ru":"От уличной еды на Старом рынке до роскошного морепродуктового ужина на закате — быстрый тур по местам, где едят местные жители.","de":"Vom Street Food auf dem Alten Markt bis zum Sonnenuntergangs-Meeresfrüchte-Schlemmen — eine kurze Tour zu den Orten, an denen Einheimische wirklich essen.","it":"Dallo street food del Vecchio Mercato a una cena di pesce al tramonto — un rapido tour dei luoghi dove mangiano davvero i residenti.","tr":"Eski Çarşı sokak lezzetlerinden gün batımında deniz ürünleri ziyafetine — yerlilerin gerçekten yediği yerlere hızlı bir tur."},"content":{"en":"Sharm's dining scene stretches from humble street stalls to some genuinely special-occasion tables. Start in the Old Market in the early evening, where grilled kofta stands and fresh juice bars line the lanes — it's the cheapest and most local meal you'll find in town. For a sit-down dinner, the city's Indian and Italian kitchens punch above their weight, a legacy of decades serving an international crowd; expect proper tandoori and wood-fired pizza rather than tourist-menu versions. Save one night for seafood — the pier restaurants along Ras Um Sid let you pick your fish straight off the ice and watch it grilled, best enjoyed as the sun goes down over the water. And don't skip the simple pleasures: a glass of hot karkade (hibiscus tea) and shisha at a beachfront cafe is as much a part of a Sharm evening as any meal.","ar":"يمتد مشهد الطعام في شرم الشيخ من الأكشاك المتواضعة إلى موائد مناسبات خاصة حقيقية. ابدأ في السوق القديم في المساء الباكر، حيث تصطف أكشاك الكفتة المشوية وعصائر طازجة على طول الأزقة — إنها أرخص وأكثر وجبة محلية ستجدها في المدينة. لعشاء جالس، تتفوق مطابخ المدينة الهندية والإيطالية على حجمها، وهو إرث عقود من خدمة جمهور عالمي؛ توقع تندوري حقيقي وبيتزا مخبوزة على الحطب بدلاً من نسخ قوائم السياح. احتفظ بليلة لتناول المأكولات البحرية — تتيح لك مطاعم الرصيف على طول رأس أم سيد اختيار سمكك مباشرة من الثلج ومشاهدته يُشوى.","ru":"Гастрономическая сцена Шарма простирается от скромных уличных ларьков до по-настоящему особенных столов. Начните со Старого рынка ранним вечером, где вдоль улочек выстроились киоски с жареной кофтой и свежими соками.","de":"Sharms Gastronomieszene reicht von bescheidenen Straßenständen bis zu wirklich besonderen Tischen für besondere Anlässe. Beginnen Sie am frühen Abend auf dem Alten Markt, wo gegrillte Kofta-Stände und frische Saftbars die Gassen säumen.","it":"La scena gastronomica di Sharm si estende da umili bancarelle di strada a tavoli davvero speciali per le occasioni importanti. Inizia al Vecchio Mercato nel primo pomeriggio, dove bancarelle di kofta alla griglia e bar di succhi freschi fiancheggiano i vicoli.","tr":"Sharm'ın yemek sahnesi mütevazı sokak tezgahlarından gerçekten özel günler için masalara kadar uzanır. Erken akşam saatlerinde, ızgara köfte tezgahları ve taze meyve suyu barlarının sokakları süslediği Eski Çarşı'dan başlayın."},"image":"https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=900&q=85","author":"Discover Sharm Editorial","readTimeMinutes":4}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('article', 'a4', 40, true, $ds${"id":"a4","title":{"en":"Airport to Hotel: What to Expect From Your Transfer","ar":"من المطار إلى الفندق: ماذا تتوقع من ترانسفيرك","ru":"Из аэропорта в отель: чего ожидать от трансфера","de":"Vom Flughafen zum Hotel: Was Sie von Ihrem Transfer erwarten können","it":"Dall'aeroporto all'hotel: cosa aspettarsi dal tuo transfer","tr":"Havalimanından Otele: Transferinizden Ne Beklemelisiniz"},"excerpt":{"en":"How airport pickup works, where to find your driver, and tips for a smooth first hour in Sharm.","ar":"كيف يعمل استقبال المطار، وأين تجد سائقك، ونصائح لساعة أولى سلسة في شرم.","ru":"Как работает встреча в аэропорту, где найти водителя и советы для гладкого первого часа в Шарме.","de":"Wie die Flughafenabholung funktioniert, wo Sie Ihren Fahrer finden, und Tipps für eine reibungslose erste Stunde in Sharm.","it":"Come funziona il ritiro in aeroporto, dove trovare il tuo autista e consigli per una prima ora senza intoppi a Sharm.","tr":"Havalimanı karşılamanın nasıl çalıştığı, şoförünüzü nerede bulacağınız ve Sharm'daki sorunsuz bir ilk saat için ipuçları."},"content":{"en":"After a long flight, the last thing you want is uncertainty about getting to your hotel — here's how it works when you book a transfer with us. Once your flight lands, head through passport control and baggage claim as normal; your driver will be waiting in the arrivals hall holding a sign with your name, usually near the exit doors. Our vehicles are air-conditioned tourist-class Hyundai H1s, comfortable for up to seven passengers with luggage, and the fare is fixed at booking — no meter, no surprise charges. If your flight is delayed, no need to worry: we track flight numbers and adjust pickup timing automatically. The drive from the airport into central Sharm typically takes 20–35 minutes depending on your hotel's location. On departure day, the same process runs in reverse — just confirm your pickup time and address when you book, and build in a little extra buffer for the airport's security lines.","ar":"بعد رحلة طويلة، آخر ما تريده هو عدم اليقين بشأن الوصول إلى فندقك — إليك كيف يعمل الأمر عند حجز ترانسفير معنا. بمجرد هبوط رحلتك، توجه عبر الجوازات واستلام الأمتعة كالمعتاد؛ سيكون سائقك بانتظارك في صالة الوصول حاملاً لافتة باسمك، عادةً بالقرب من أبواب الخروج. سياراتنا هي هيونداي H1 سياحية مكيّفة، تتسع لسبعة ركاب مع الأمتعة، والأجرة ثابتة عند الحجز — بلا عداد وبلا رسوم مفاجئة. إذا تأخرت رحلتك، فلا داعي للقلق: نتابع أرقام الرحلات ونُعدّل توقيت الاستلام تلقائيًا.","ru":"После долгого перелёта меньше всего хочется неопределённости с тем, как добраться до отеля — вот как это работает при бронировании трансфера у нас. Как только ваш рейс приземлится, пройдите паспортный контроль и получение багажа как обычно; ваш водитель будет ждать в зале прилёта с табличкой с вашим именем.","de":"Nach einem langen Flug ist Unsicherheit darüber, wie Sie zu Ihrem Hotel gelangen, das Letzte, was Sie wollen — so funktioniert es, wenn Sie einen Transfer bei uns buchen. Sobald Ihr Flug landet, gehen Sie wie gewohnt durch die Passkontrolle und Gepäckausgabe; Ihr Fahrer wartet in der Ankunftshalle mit einem Schild mit Ihrem Namen.","it":"Dopo un volo lungo, l'ultima cosa che vuoi è l'incertezza su come arrivare al tuo hotel — ecco come funziona quando prenoti un transfer con noi. Non appena il tuo volo atterra, procedi attraverso il controllo passaporti e il ritiro bagagli come al solito; il tuo autista ti aspetterà nella sala arrivi con un cartello con il tuo nome.","tr":"Uzun bir uçuştan sonra en son istediğiniz şey otelinize nasıl gideceğinize dair belirsizliktir — bizimle transfer ayırttığınızda işler böyle yürür. Uçağınız indikten sonra pasaport kontrolü ve bagaj almadan her zamanki gibi geçin; şoförünüz varış salonunda adınızı taşıyan bir tabelayla bekliyor olacak."},"image":"https://images.unsplash.com/photo-1519003722824-194d4455a60c?auto=format&fit=crop&w=900&q=85","author":"Discover Sharm Editorial","readTimeMinutes":3}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('promo_slide', 'ps1', 10, true, $ds${"id":"ps1","title":{"en":"HSR Shooting","ar":"HSR Shooting","de":"HSR Shooting","it":"HSR Shooting","ru":"HSR Shooting","tr":"HSR Shooting"},"subtitle":{"en":"Live fire shooting experience at HSR","ar":"ضرب نار في HSR","de":"Live-Schießerlebnis bei HSR","it":"Esperienza di tiro dal vivo a HSR","ru":"Стрельба боевыми патронами в HSR","tr":"HSR'de canlı atış deneyimi"},"date":"29 أكتوبر","image":"https://images.unsplash.com/photo-1595590424283-b8f17842773f?auto=format&fit=crop&w=900&q=80","linkType":"url","linkTarget":"","order":1,"active":true}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv1', 10, true, $ds${"id":"rv1","name":"Marco B.","rating":5,"section":"excursion","itemName":{"en":"Ras Mohammed Snorkeling Trip","ar":"رحلة سنوركل رأس محمد","ru":"Снорклинг-тур в Рас-Мохаммед","de":"Ras-Mohammed-Schnorcheltour","it":"Escursione Snorkeling a Ras Mohammed","tr":"Ras Muhammed Şnorkel Turu"},"image":"https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80","text":{"en":"Booked through Discover Sharm, got a reply on WhatsApp in like 5 minutes. Trip itself was amazing too.","ar":"حجزت من ديسكفر شرم، جاوبوني عالواتساب بعد ٥ دقائق بس. والرحلة نفسها كانت جميلة جدًا.","ru":"Забронировал через Discover Sharm, ответили в WhatsApp минут за 5. Сама поездка тоже супер.","de":"Über Discover Sharm gebucht, Antwort auf WhatsApp nach 5 Minuten. Der Ausflug selbst war auch toll.","it":"Prenotato su Discover Sharm, risposta su WhatsApp in 5 minuti. Anche la gita è stata fantastica.","tr":"Discover Sharm üzerinden ayırttım, WhatsApp'ta 5 dakikada cevap geldi. Turun kendisi de harikaydı."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv2', 20, true, $ds${"id":"rv2","name":"Ahmed T.","rating":5,"section":"excursion","itemName":{"en":"White Desert Safari & BBQ Dinner","ar":"رحلة سفاري الصحراء البيضاء وعشاء شواء","ru":"Сафари в Белую пустыню и барбекю-ужин","de":"Wüstensafari & BBQ-Dinner","it":"Safari nel Deserto Bianco e cena BBQ","tr":"Beyaz Çöl Safarisi ve Barbekü Yemeği"},"image":"https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=800&q=80","text":{"en":"Easy booking from Discover Sharm's site, driver was on time, night in the desert was unreal.","ar":"الحجز من موقع ديسكفر شرم كان سهل، السائق جه في الميعاد، وليلة الصحراء كانت تحفة.","ru":"Забронировать на сайте Discover Sharm было легко, водитель приехал вовремя, ночь в пустыне — нереально.","de":"Buchung auf der Discover-Sharm-Seite war einfach, Fahrer pünktlich, die Nacht in der Wüste war unglaublich.","it":"Prenotazione facile sul sito Discover Sharm, autista puntuale, la notte nel deserto è stata pazzesca.","tr":"Discover Sharm sitesinden rezervasyon kolaydı, şoför zamanında geldi, çöldeki gece muhteşemdi."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv3', 30, true, $ds${"id":"rv3","name":"Dimitri V.","rating":5,"section":"transfer","itemName":{"en":"VIP Hiace AC Airport Transfer","ar":"ترانسفير مطار VIP هايس مكيف","ru":"VIP-трансфер Hiace с кондиционером","de":"VIP-Hiace-Flughafentransfer mit Klimaanlage","it":"Transfer aeroportuale VIP Hiace con aria condizionata","tr":"VIP Klimalı Hiace Havalimanı Transferi"},"image":"https://images.unsplash.com/photo-1502877338535-766e1452684a?auto=format&fit=crop&w=800&q=80","text":{"en":"Flight was delayed 5 hours and the driver was still there waiting with cold water. Thank you Discover Sharm.","ar":"الطيارة اتأخرت ٥ ساعات والسائق كان لسه مستنينا بمية باردة. شكرًا ديسكفر شرم.","ru":"Рейс задержали на 5 часов, а водитель всё равно ждал нас с холодной водой. Спасибо, Discover Sharm.","de":"Flug hatte 5 Stunden Verspätung, der Fahrer wartete trotzdem mit kaltem Wasser. Danke, Discover Sharm.","it":"Volo in ritardo di 5 ore e l'autista era ancora lì con acqua fredda. Grazie Discover Sharm.","tr":"Uçak 5 saat gecikti ve şoför hâlâ soğuk suyla bekliyordu. Teşekkürler Discover Sharm."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv4', 40, true, $ds${"id":"rv4","name":"Olga P.","rating":5,"section":"excursion","itemName":{"en":"Blue Hole Dahab Snorkeling & Diving Trip","ar":"رحلة سنوركل وغطس البحر الأزرق دهب","ru":"Снорклинг и дайвинг в Голубой дыре, Дахаб","de":"Blue Hole Dahab Schnorchel- & Tauchtour","it":"Escursione Snorkeling e Diving al Blue Hole di Dahab","tr":"Dahab Mavi Delik Şnorkel ve Dalış Turu"},"image":"https://images.unsplash.com/photo-1544551763-92ab472cad5d?auto=format&fit=crop&w=800&q=80","text":{"en":"Everything on the Discover Sharm listing matched reality, no surprises. Water was insane.","ar":"كل حاجة مكتوبة في إعلان ديسكفر شرم كانت زي ما هي بالظبط، مفيش مفاجآت. المية كانت جنان.","ru":"Всё, что написано у Discover Sharm, совпало с реальностью, без сюрпризов. Вода — нечто.","de":"Alles bei Discover Sharm beschrieben passte zur Realität, keine Überraschungen. Wasser war irre.","it":"Tutto quello scritto da Discover Sharm corrispondeva alla realtà, nessuna sorpresa. Acqua pazzesca.","tr":"Discover Sharm'ın ilanındaki her şey gerçekle birebir aynıydı, sürpriz yok. Su inanılmazdı."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv5', 50, true, $ds${"id":"rv5","name":"Priya N.","rating":5,"section":"transfer","itemName":{"en":"Private Minivan Hotel-to-Hotel Transfer","ar":"ترانسفير خاص من فندق إلى فندق بفان مكيف","ru":"Частный трансфер на микроавтобусе от отеля к отелю","de":"Privater Minivan-Transfer von Hotel zu Hotel","it":"Transfer privato in minivan da hotel a hotel","tr":"Otelden Otele Özel Klimalı Minivan Transferi"},"image":"https://images.unsplash.com/photo-1519003722824-194d4455a60c?auto=format&fit=crop&w=800&q=80","text":{"en":"Changed our transfer time twice, Discover Sharm's team sorted it both times, no extra fees.","ar":"غيّرنا ميعاد الترانسفير مرتين وفريق ديسكفر شرم ظبطها المرتين من غير رسوم إضافية.","ru":"Дважды меняли время трансфера, команда Discover Sharm всё уладила без доплат.","de":"Transferzeit zweimal geändert, das Discover-Sharm-Team hat es beide Male ohne Zusatzkosten gelöst.","it":"Cambiato l'orario del transfer due volte, il team di Discover Sharm ha sistemato tutto senza costi extra.","tr":"Transfer saatimizi iki kez değiştirdik, Discover Sharm ekibi ikisinde de ek ücret almadan halletti."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv6', 60, true, $ds${"id":"rv6","name":"Klaus M.","rating":5,"section":"excursion","itemName":{"en":"Tiran Island Boat Trip","ar":"رحلة بحرية إلى جزيرة تيران","ru":"Морская прогулка на остров Тиран","de":"Bootsausflug zur Insel Tiran","it":"Gita in barca all'isola di Tiran","tr":"Tiran Adası Tekne Turu"},"image":"https://images.unsplash.com/photo-1544551763-77ef2d0cfc6c?auto=format&fit=crop&w=800&q=80","text":{"en":"No hidden fees at checkout, that alone made me trust Discover Sharm. Boat trip was great too.","ar":"مفيش رسوم مخفية عند الدفع، ده بس خلاني أثق في ديسكفر شرم. ورحلة القارب كانت جميلة برضو.","ru":"Никаких скрытых сборов при оплате — уже одно это вызвало доверие к Discover Sharm. Поездка тоже отличная.","de":"Keine versteckten Gebühren beim Checkout, allein das hat mein Vertrauen in Discover Sharm gewonnen.","it":"Nessuna commissione nascosta al checkout, solo questo mi ha fatto fidare di Discover Sharm.","tr":"Ödemede gizli ücret yoktu, bu bile Discover Sharm'a güvenmemi sağladı. Tekne turu da güzeldi."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv7', 70, true, $ds${"id":"rv7","name":"Youssef E.","rating":5,"section":"excursion","itemName":{"en":"Quad Bike Desert Sunset Safari","ar":"رحلة سفاري الدراجات الرباعية عند الغروب","ru":"Сафари на квадроциклах в пустыне на закате","de":"Quad-Wüstensafari bei Sonnenuntergang","it":"Safari nel deserto in quad al tramonto","tr":"Çölde Gün Batımı ATV Safarisi"},"image":"https://images.unsplash.com/photo-1451337516015-6b6e9a44a8a3?auto=format&fit=crop&w=800&q=80","text":{"en":"My mom called their support line before booking and someone answered in Arabic right away. She was happy, I was happy.","ar":"أمي اتصلت بالدعم قبل الحجز وردوا عليها بالعربي على طول. هي فرحت وأنا فرحت.","ru":"Мама позвонила в поддержку перед бронированием, ей сразу ответили по-арабски. Она была довольна, и я тоже.","de":"Meine Mutter rief vor der Buchung die Support-Hotline an, es wurde sofort auf Arabisch geantwortet.","it":"Mia madre ha chiamato l'assistenza prima di prenotare, hanno risposto subito in arabo.","tr":"Annem rezervasyondan önce destek hattını aradı ve hemen Arapça cevap verdiler. O mutluydu, ben mutluydum."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv8', 80, true, $ds${"id":"rv8","name":"Helena D.","rating":5,"section":"excursion","itemName":{"en":"Colored Canyon & St. Catherine Day Trip","ar":"رحلة يوم كامل للكانيون الملون ودير سانت كاترين","ru":"Однодневная поездка в Цветной каньон и монастырь Св. Екатерины","de":"Tagesausflug zum Colored Canyon & Katharinenkloster","it":"Gita di un giorno al Canyon Colorato e Santa Caterina","tr":"Renkli Kanyon ve Aziz Katerina Manastırı Günübirlik Turu"},"image":"https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?auto=format&fit=crop&w=800&q=80","text":{"en":"6am pickup and the van showed up 2 minutes early. Small thing but it says a lot.","ar":"الاستلام كان الساعة ٦ الصبح والعربية جت قبل الميعاد بدقيقتين. حاجة صغيرة بس بتقول كتير.","ru":"Встреча в 6 утра, машина приехала на 2 минуты раньше. Мелочь, но многое говорит.","de":"Abholung um 6 Uhr, der Van war 2 Minuten früher da. Kleinigkeit, sagt aber viel aus.","it":"Ritiro alle 6, il furgone è arrivato 2 minuti prima. Piccola cosa ma dice molto.","tr":"Sabah 6 alışı ve minibüs 2 dakika erken geldi. Küçük bir şey ama çok şey anlatıyor."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv9', 90, true, $ds${"id":"rv9","name":"Chen L.","rating":5,"section":"excursion","itemName":{"en":"Ras Mohammed Snorkeling Trip","ar":"رحلة سنوركل رأس محمد","ru":"Снорклинг-тур в Рас-Мохаммед","de":"Ras-Mohammed-Schnorcheltour","it":"Escursione Snorkeling a Ras Mohammed","tr":"Ras Muhammed Şnorkel Turu"},"image":"https://images.unsplash.com/photo-1583212292454-1fe6229603b7?auto=format&fit=crop&w=800&q=80","text":{"en":"Lost my mask on the boat, Discover Sharm actually tracked it down and sent it to my hotel next day. Didn't expect that.","ar":"ضيعت نضارتي على القارب، وديسكفر شرم فعلاً لقوها ووصلوها لفندقي تاني يوم. ما كنتش متوقع كده.","ru":"Потерял маску на лодке, Discover Sharm нашли её и доставили в отель на следующий день. Не ожидал.","de":"Maske auf dem Boot verloren, Discover Sharm hat sie gefunden und am nächsten Tag ins Hotel geschickt.","it":"Persa la maschera in barca, Discover Sharm l'ha trovata e mandata in hotel il giorno dopo.","tr":"Maskemi teknede kaybettim, Discover Sharm buldu ve ertesi gün otelime gönderdi. Beklemiyordum."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv10', 100, true, $ds${"id":"rv10","name":"Nadia R.","rating":5,"section":"transfer","itemName":{"en":"Tourist H1 Airport Transfer","ar":"ترانسفير مطار H1 سياحي","ru":"Туристический трансфер H1","de":"Touristen-H1-Flughafentransfer","it":"Transfer aeroportuale H1 turistico","tr":"Turistik H1 Havalimanı Transferi"},"image":"https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?auto=format&fit=crop&w=800&q=80","text":{"en":"Flight number changed twice, updated it myself on Discover Sharm's site in two taps. Easy.","ar":"رقم الرحلة اتغير مرتين، عدلته بنفسي في موقع ديسكفر شرم بضغطتين بس. سهل جدًا.","ru":"Номер рейса менялся дважды, обновил сам на сайте Discover Sharm в два клика. Просто.","de":"Flugnummer zweimal geändert, selbst auf der Discover-Sharm-Seite mit zwei Klicks aktualisiert. Einfach.","it":"Numero di volo cambiato due volte, aggiornato da solo sul sito Discover Sharm in due tocchi. Facile.","tr":"Uçuş numarası iki kez değişti, Discover Sharm sitesinden kendim iki dokunuşla güncelledim. Kolay."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv11', 110, true, $ds${"id":"rv11","name":"Sara H.","rating":4,"section":"excursion","itemName":{"en":"Blue Hole Dahab Snorkeling & Diving Trip","ar":"رحلة سنوركل وغطس البحر الأزرق دهب","ru":"Снорклинг и дайвинг в Голубой дыре, Дахаб","de":"Blue Hole Dahab Schnorchel- & Tauchtour","it":"Escursione Snorkeling e Diving al Blue Hole di Dahab","tr":"Dahab Mavi Delik Şnorkel ve Dalış Turu"},"image":"https://images.unsplash.com/photo-1544551763-92ab472cad5d?auto=format&fit=crop&w=800&q=80","text":{"en":"Drive back was long, mentioned it in the feedback form and actually got a reply from Discover Sharm the next day.","ar":"طريق العودة كان طويل، كتبته في نموذج الملاحظات واستلمت رد فعلي من ديسكفر شرم تاني يوم.","ru":"Обратная дорога была долгой, написал в форме обратной связи и правда получил ответ от Discover Sharm на следующий день.","de":"Rückfahrt war lang, im Feedback-Formular erwähnt und tatsächlich eine Antwort von Discover Sharm erhalten.","it":"Viaggio di ritorno lungo, l'ho scritto nel modulo feedback e ho davvero ricevuto una risposta da Discover Sharm.","tr":"Dönüş yolu uzundu, geri bildirim formuna yazdım ve gerçekten Discover Sharm'dan ertesi gün cevap geldi."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv12', 120, true, $ds${"id":"rv12","name":"Robert F.","rating":5,"section":"transfer","itemName":{"en":"Group Shuttle Airport Transfer","ar":"ترانسفير مطار جماعي (شاتل)","ru":"Групповой шаттл-трансфер в аэропорт","de":"Gruppen-Shuttle-Flughafentransfer","it":"Transfer aeroportuale navetta di gruppo","tr":"Grup Servisi Havalimanı Transferi"},"image":"https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=800&q=80","text":{"en":"Cheapest option but van was AC and clean. Discover Sharm grouped us with people near our hotel, fewer stops.","ar":"أرخص خيار بس الفان كان مكيف ونظيف. ديسكفر شرم جمعونا مع ناس قريبة من فندقنا، توقفات أقل.","ru":"Самый дешёвый вариант, но микроавтобус с кондиционером и чистый. Discover Sharm сгруппировали нас с людьми рядом с нашим отелем.","de":"Günstigste Option, aber Van war klimatisiert und sauber. Discover Sharm gruppierte uns mit Leuten nahe unserem Hotel.","it":"Opzione più economica ma il furgone era climatizzato e pulito. Discover Sharm ci ha raggruppato vicino al nostro hotel.","tr":"En ucuz seçenekti ama minibüs klimalı ve temizdi. Discover Sharm bizi otelimize yakın kişilerle gruplandırdı."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv13', 130, true, $ds${"id":"rv13","name":"Fatima A.","rating":5,"section":"excursion","itemName":{"en":"Colored Canyon & St. Catherine Day Trip","ar":"رحلة يوم كامل للكانيون الملون ودير سانت كاترين","ru":"Однодневная поездка в Цветной каньон и монастырь Св. Екатерины","de":"Tagesausflug zum Colored Canyon & Katharinenkloster","it":"Gita di un giorno al Canyon Colorato e Santa Caterina","tr":"Renkli Kanyon ve Aziz Katerina Manastırı Günübirlik Turu"},"image":"https://images.unsplash.com/photo-1533640470979-4d0a55850c30?auto=format&fit=crop&w=800&q=80","text":{"en":"Wrote a note about my dad's wheelchair at checkout, Discover Sharm called within the hour to sort out the details.","ar":"كتبت ملاحظة عن كرسي بابا المتحرك عند الدفع، ديسكفر شرم اتصلوا خلال ساعة عشان يظبطوا التفاصيل.","ru":"Написала заметку про инвалидную коляску отца при оформлении, Discover Sharm перезвонили в течение часа.","de":"Notiz zum Rollstuhl meines Vaters beim Checkout hinterlassen, Discover Sharm rief innerhalb einer Stunde an.","it":"Scritta una nota sulla sedia a rotelle di mio padre al checkout, Discover Sharm ha chiamato entro un'ora.","tr":"Ödemede babamın tekerlekli sandalyesiyle ilgili not yazdım, Discover Sharm bir saat içinde arayıp detayları ayarladı."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv14', 140, true, $ds${"id":"rv14","name":"Julia S.","rating":5,"section":"excursion","itemName":{"en":"Tiran Island Boat Trip","ar":"رحلة بحرية إلى جزيرة تيران","ru":"Морская прогулка на остров Тиран","de":"Bootsausflug zur Insel Tiran","it":"Gita in barca all'isola di Tiran","tr":"Tiran Adası Tekne Turu"},"image":"https://images.unsplash.com/photo-1544551763-77ef2d0cfc6c?auto=format&fit=crop&w=800&q=80","text":{"en":"5 stars, simple as that. Discover Sharm made booking easy and the trip delivered.","ar":"٥ نجوم، بكل بساطة. ديسكفر شرم سهّلوا الحجز والرحلة كانت زي المتوقع بالظبط.","ru":"5 звёзд, просто и понятно. Discover Sharm упростили бронирование, поездка не разочаровала.","de":"5 Sterne, ganz einfach. Discover Sharm machte die Buchung leicht, der Ausflug hat gehalten was er versprach.","it":"5 stelle, semplice. Discover Sharm ha reso facile la prenotazione, la gita ha mantenuto le promesse.","tr":"5 yıldız, basitçe. Discover Sharm rezervasyonu kolaylaştırdı, tur sözünü tuttu."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv15', 150, true, $ds${"id":"rv15","name":"Mariam Z.","rating":5,"section":"excursion","itemName":{"en":"White Desert Safari & BBQ Dinner","ar":"رحلة سفاري الصحراء البيضاء وعشاء شواء","ru":"Сафари в Белую пустыню и барбекю-ужин","de":"Wüstensafari & BBQ-Dinner","it":"Safari nel Deserto Bianco e cena BBQ","tr":"Beyaz Çöl Safarisi ve Barbekü Yemeği"},"image":"https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=800&q=80","text":{"en":"Asked Discover Sharm if the quad bikes were ok for a beginner, they said yes and they were right. Loved it.","ar":"سألت ديسكفر شرم لو الدراجات مناسبة لمبتدئة، قالوا آه وكانوا صح. حبيت الرحلة جدًا.","ru":"Спросила у Discover Sharm, подойдут ли квадроциклы новичку, сказали да — и оказались правы. Очень понравилось.","de":"Discover Sharm gefragt, ob die Quads für Anfänger okay sind, sie sagten ja und hatten recht. Hat mir gefallen.","it":"Ho chiesto a Discover Sharm se i quad andassero bene per una principiante, hanno detto sì ed è stato vero. Mi è piaciuto molto.","tr":"Discover Sharm'a ATV'lerin yeni başlayan için uygun olup olmadığını sordum, evet dediler ve haklıydılar. Çok sevdim."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv16', 160, true, $ds${"id":"rv16","name":"Tom R.","rating":5,"section":"transfer","itemName":{"en":"VIP Hiace AC Airport Transfer","ar":"ترانسفير مطار VIP هايس مكيف","ru":"VIP-трансфер Hiace с кондиционером","de":"VIP-Hiace-Flughafentransfer mit Klimaanlage","it":"Transfer aeroportuale VIP Hiace con aria condizionata","tr":"VIP Klimalı Hiace Havalimanı Transferi"},"image":"https://images.unsplash.com/photo-1502877338535-766e1452684a?auto=format&fit=crop&w=800&q=80","text":{"en":"Booked last minute at midnight, still got a driver at the airport by 6am. Solid.","ar":"حجزت في آخر لحظة الساعة ١٢ بالليل، ولسه لقيت سائق في المطار الساعة ٦ الصبح. ممتاز.","ru":"Забронировал в последний момент в полночь, но водитель уже был в аэропорту к 6 утра. Отлично.","de":"In letzter Minute um Mitternacht gebucht, trotzdem stand um 6 Uhr ein Fahrer am Flughafen. Solide.","it":"Prenotato all'ultimo minuto a mezzanotte, comunque un autista era all'aeroporto alle 6. Ottimo.","tr":"Gece yarısı son dakika ayırttım, yine de sabah 6'da havalimanında şoför vardı. Gayet iyi."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv17', 170, true, $ds${"id":"rv17","name":"Aya M.","rating":4,"section":"excursion","itemName":{"en":"Colored Canyon & St. Catherine Day Trip","ar":"رحلة يوم كامل للكانيون الملون ودير سانت كاترين","ru":"Однодневная поездка в Цветной каньон и монастырь Св. Екатерины","de":"Tagesausflug zum Colored Canyon & Katharinenkloster","it":"Gita di un giorno al Canyon Colorato e Santa Caterina","tr":"Renkli Kanyon ve Aziz Katerina Manastırı Günübirlik Turu"},"image":"https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?auto=format&fit=crop&w=800&q=80","text":{"en":"Long day, bring snacks. Booking with Discover Sharm was straightforward though.","ar":"يوم طويل، خدوا معاكم أكل خفيف. بس الحجز من ديسكفر شرم كان بسيط جدًا.","ru":"Долгий день, берите перекус. Но бронирование через Discover Sharm было простым.","de":"Langer Tag, Snacks mitnehmen. Buchung bei Discover Sharm war aber unkompliziert.","it":"Giornata lunga, portate snack. La prenotazione con Discover Sharm però è stata semplice.","tr":"Uzun bir gün, atıştırmalık alın. Ama Discover Sharm ile rezervasyon çok kolaydı."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv18', 180, true, $ds${"id":"rv18","name":"Michael O.","rating":5,"section":"transfer","itemName":{"en":"Private Minivan Hotel-to-Hotel Transfer","ar":"ترانسفير خاص من فندق إلى فندق بفان مكيف","ru":"Частный трансфер на микроавтобусе от отеля к отелю","de":"Privater Minivan-Transfer von Hotel zu Hotel","it":"Transfer privato in minivan da hotel a hotel","tr":"Otelden Otele Özel Klimalı Minivan Transferi"},"image":"https://images.unsplash.com/photo-1519003722824-194d4455a60c?auto=format&fit=crop&w=800&q=80","text":{"en":"Clean van, driver knew a shortcut and got us there faster than Google Maps said. Booked via Discover Sharm.","ar":"فان نظيف والسائق كان عارف طريق مختصر ووصلنا أسرع من جوجل ماب. حجزت من ديسكفر شرم.","ru":"Чистый микроавтобус, водитель знал короткий путь и довёз нас быстрее, чем показывал Google Карты.","de":"Sauberer Van, Fahrer kannte eine Abkürzung, wir waren schneller da als Google Maps sagte.","it":"Furgone pulito, l'autista conosceva una scorciatoia e siamo arrivati prima di quanto dicesse Google Maps.","tr":"Temiz minibüs, şoför kestirme biliyordu ve Google Haritalar'ın dediğinden daha hızlı vardık."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv19', 190, true, $ds${"id":"rv19","name":"Layla H.","rating":5,"section":"excursion","itemName":{"en":"Blue Hole Dahab Snorkeling & Diving Trip","ar":"رحلة سنوركل وغطس البحر الأزرق دهب","ru":"Снорклинг и дайвинг в Голубой дыре, Дахаб","de":"Blue Hole Dahab Schnorchel- & Tauchtour","it":"Escursione Snorkeling e Diving al Blue Hole di Dahab","tr":"Dahab Mavi Delik Şnorkel ve Dalış Turu"},"image":"https://images.unsplash.com/photo-1544551763-92ab472cad5d?auto=format&fit=crop&w=800&q=80","text":{"en":"Rescheduled because of weather, Discover Sharm moved us to the next day free of charge, no argument.","ar":"أجلنا الرحلة بسبب الجو، وديسكفر شرم نقلونا لليوم اللي بعده مجانًا من غير أي جدال.","ru":"Перенесли из-за погоды, Discover Sharm бесплатно перенесли нас на следующий день, без споров.","de":"Wegen Wetter verschoben, Discover Sharm hat uns kostenlos auf den nächsten Tag umgebucht, ohne Diskussion.","it":"Rinviata per il maltempo, Discover Sharm ci ha spostati al giorno dopo gratis, senza discutere.","tr":"Hava yüzünden ertelendi, Discover Sharm bizi tartışmasız ücretsiz ertesi güne aldı."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;
insert into public.site_content (kind, id, sort_order, published, data) values ('testimonial', 'rv20', 200, true, $ds${"id":"rv20","name":"Karim S.","rating":5,"section":"transfer","itemName":{"en":"Tourist H1 Airport Transfer","ar":"ترانسفير مطار H1 سياحي","ru":"Туристический трансфер H1","de":"Touristen-H1-Flughafentransfer","it":"Transfer aeroportuale H1 turistico","tr":"Turistik H1 Havalimanı Transferi"},"image":"https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?auto=format&fit=crop&w=800&q=80","text":{"en":"Simple, on time, driver spoke enough English to chat the whole ride. Would use Discover Sharm again.","ar":"بسيط، في الميعاد، والسائق كلامه إنجليزي كويس اتكلمنا طول الطريق. هحجز من ديسكفر شرم تاني أكيد.","ru":"Просто, вовремя, водитель говорил на достаточном английском, чтобы болтать всю дорогу.","de":"Einfach, pünktlich, der Fahrer sprach genug Englisch, um die ganze Fahrt zu plaudern.","it":"Semplice, puntuale, l'autista parlava abbastanza inglese da chiacchierare per tutto il tragitto.","tr":"Basit, zamanında, şoför yol boyunca sohbet edecek kadar İngilizce biliyordu."}}$ds$::jsonb)
  on conflict (kind, id) do update set data = excluded.data, sort_order = excluded.sort_order, published = excluded.published;

commit;
